"""Shared contact/motion callback callers and ordered roster callback replacement."""
import hashlib,json
from pathlib import Path
from inventory_rom import ROM_HASH
from m68k_static import Decoder
p=Path(__file__).resolve().parents[1];root=p.parents[1];rom=(p/'local/rolo.md').read_bytes();assert hashlib.sha256(rom).hexdigest()==ROM_HASH
rp=root/'work/actor-common-callbacks-results.json';r=json.loads(rp.read_text(encoding='utf-8-sig'));assert r==dict(passed=True,**{k:65536 for k in ['E14E','E1CE','D89E','E1BC','E478','E776','EF3C','E798']})
sources=['src/core/actor_common_callbacks.hpp','src/core/first_enemy.hpp','src/core/actor_motion.hpp','src/core/actor_allocation.hpp','src/core/actor_state.hpp','tests/actor_common_callbacks_verification_tests.cpp'];exe=root/'work/actor_common_callbacks_verification_tests.exe';assert exe.stat().st_mtime>=max((p/s).stat().st_mtime for s in sources)
inv=json.loads((p/'docs/stage9/inventory.json').read_text(encoding='utf-8'));accepted={a for x in inv['routines'] for a in x['blocks']};records=[]
specs=[(0xe14e,0xe15e,'Object contact then player contact; reached contact invokes damage, no inactive gate.'),(0xe1ce,0xe1f6,'Same contact order then fetch live controlled actor, wrapped X subtraction N controls full facing BYTE replacement0/8.'),(0xd89e,0xd8be,'Any inactive117 gates all work; otherwise contacts, integer step3 retaining fractions and velocity lowword, direction service after step even if contact changes inactive flag.'),(0xe1bc,0xe1ce,'Contact then direct976C hit when reached; unconditional integer step6 after hit, preserving fractions.'),(0xe478,0xe48c,'Contact then direct hit; gravity then integration, no landing query.'),(0xe776,0xe798,'Groundbit sets upward directionFF/magnitude30000 before gravity/integration, then landing handoff.'),(0xef3c,0xef68,'F2B8 zero admits player contact/direct hit. Then retirement116 reflects live117; add speed highWORDs58/62 to integerXY only, retaining fractions.'),(0xe798,0xe7be,'Count0 returns; otherwise live roster order, immutable definition type WORD equality writes callbackLONG42. Repeated actor aliases observe earlier callback writes.')]
for start,end,contract in specs:
 at=start;items=[]
 while at<end:
  assert at in accepted;i=Decoder(rom,at).decode();items.append(i);at+=i['size']
 assert at==end
 records.append(dict(address=start,hex=f'{start:06X}',end_exclusive=end,original_bytes=rom[start:end].hex(),instruction_evidence=items,verification_status='verified',status='verified green: local shared actor callback',native_sources=[sources[0]],checked_cases=65536,contract=contract,proof='Independent caller state/order models;65536 cases each. AllBYTE flags/inactive/direction patterns, wrapped position/velocity values and actor/controlled aliases; services mutate actor flags, coordinates and controlled identity before subsequent reads. Compare all48 records, controlled identity and ordered calls. Roster tests counts0..48, repeated aliases and exact type matches/misses with lookup observation of prior callback writes. Green gravity/integration/integer-step are reused child contracts, not re-certified.',scope='Local caller contracts with valid stable actor record and finite roster<=48. Contact, direct976C damage, direction and landing remain explicit service handoffs, whose separate implementations/caller admission are not proved here. New typed helpers available for later playable callback binding; no scene or whole-level certificate.'))
report=dict(rom_sha256=ROM_HASH,source_sha256={s:hashlib.sha256((p/s).read_bytes()).hexdigest() for s in sources},records=records,test_executable_sha256=hashlib.sha256(exe.read_bytes()).hexdigest(),results_sha256=hashlib.sha256(rp.read_bytes()).hexdigest())
(p/'docs/stage9/actor-common-callbacks-verification.json').write_text(json.dumps(report,indent=2)+'\n',encoding='utf-8');print('Eight shared actor caller contracts verified.')
